const items = $input.all();
const today = new Date();
const results = [];

const milestones = {
  1: {
    title: 'Day 1: Welcome!',
    message: ':wave: *Welcome to your first day!*\n\nHere\'s what to do today:\n\n1. :lock: Set up your accounts (email, Slack, GitHub)\n2. :book: Read the employee handbook: [link]\n3. :handshake: Meet your buddy — they\'ll reach out today\n4. :computer: Set up your development environment\n5. :calendar: Check your calendar for orientation sessions'
  },
  3: {
    title: 'Day 3: Getting Settled',
    message: ':rocket: *Day 3 Check-in*\n\nYou\'re settling in! Today\'s focus:\n\n1. :git: Complete your first PR (even if it\'s just a README update)\n2. :busts_in_silhouette: Introduce yourself in #introductions\n3. :question: Write down any questions for your 1:1\n4. :books: Review team documentation and architecture docs'
  },
  7: {
    title: 'Day 7: First Week Complete!',
    message: ':tada: *One week done!*\n\nEnd of first week checklist:\n\n1. :white_check_mark: Ensure all access is working\n2. :speech_balloon: Schedule coffee chats with 3 team members\n3. :memo: Document anything confusing for future new hires\n4. :calendar: Confirm recurring meeting invites\n5. :star: Share your first-week feedback'
  },
  14: {
    title: 'Day 14: Two Week Milestone',
    message: ':muscle: *Two weeks in!*\n\nBy now you should:\n\n1. :hammer_and_wrench: Have completed 2-3 tasks independently\n2. :brain: Understand the team\'s sprint process\n3. :speech_balloon: Have had your first 1:1 with your manager\n4. :dart: Have clarity on your 30/60/90 day goals'
  },
  30: {
    title: 'Day 30: First Month!',
    message: ':trophy: *Congratulations on your first month!*\n\n:clipboard: *30-Day Review:*\n\n1. :chart_with_upwards_trend: Schedule your 30-day review with your manager\n2. :memo: Prepare a summary of what you\'ve learned\n3. :bulb: Share improvement suggestions\n4. :dart: Confirm your 60-day goals\n5. :pizza: Celebrate — you\'ve made it through the hardest part!'
  }
};

for (const item of items) {
  const hire = item.json;
  const startDate = new Date(hire.start_date || hire.startDate);
  if (isNaN(startDate.getTime())) continue;

  const daysSinceStart = Math.floor((today - startDate) / (1000 * 60 * 60 * 24));

  if (milestones[daysSinceStart]) {
    results.push({
      json: {
        name: hire.name || '',
        slackUserId: hire.slack_user_id || hire.slackUserId || '',
        day: daysSinceStart,
        ...milestones[daysSinceStart],
        startDate: hire.start_date || hire.startDate
      }
    });
  }
}

if (results.length === 0) {
  return [{json: {skip: true, message: 'No onboarding messages to send today'}}];
}

return results;
